// The docs site's sidebar, kept out of `astro.config.mjs` so a test can read it.
// `site-map.test.ts` checks that every page in `PUBLISHED_EN_FILES` is reachable
// from here: a page that is synced and built but sits in no autogenerated
// directory and behind no link is an orphan nobody navigates to (TPL-2005).

/** A sidebar entry, the subset of Starlight's shape this site uses. */
export type SidebarEntry =
  | { label: string; link: string }
  | { autogenerate: { directory: string } }
  | { label: string; items: SidebarEntry[] };

export const SIDEBAR: SidebarEntry[] = [
  { label: "Guides", items: [{ autogenerate: { directory: "guide" } }] },
  { label: "Tools", items: [{ autogenerate: { directory: "tools" } }] },
  { label: "Reference", items: [{ autogenerate: { directory: "spec" } }] },
  { label: "Concepts", link: "/concepts/" },
  { label: "Keystone glossary", link: "/glossary/" },
  {
    label: "Examples",
    items: [{ label: "Overview", link: "/examples/" }, { autogenerate: { directory: "examples" } }],
  },
];

/** Every route the sidebar reaches: autogenerated directories and explicit links. */
export function sidebarReach(entries: SidebarEntry[] = SIDEBAR): {
  directories: Set<string>;
  links: Set<string>;
} {
  const directories = new Set<string>();
  const links = new Set<string>();
  const walk = (list: SidebarEntry[]): void => {
    for (const entry of list) {
      if ("autogenerate" in entry) directories.add(entry.autogenerate.directory);
      else if ("link" in entry) links.add(entry.link);
      else walk(entry.items);
    }
  };
  walk(entries);
  return { directories, links };
}
